371: pub fn build_loudness_layers_pcm16(
372:     pcm: &[i16],
373:     frames: usize,

378:     let required = frames
379:         .checked_mul(channels)
380:         .ok_or(ReaPeaksError::InvalidArgument("frames*channels overflow"))?;
381:     if pcm.len() < required {
382:         return Err(ReaPeaksError::InvalidArgument(
383:             "PCM buffer shorter than frames*channels",
384:         ));
385:     }
386:     build_loudness_layers(frames, channels, sample_rate, divisions, |index| {
387:         f64::from(pcm[index]) / 32_768.0
388:     })
389: }
